# coding: utf-8
import json
from pathlib import Path
from lesson_authoring import entry as E
V=[['拉丁语 vacare／vacuus','空着、闲着／空的']]
EV=V+[['拉丁 e-〔ex-〕+ vacuus → evacuare','使空出来、排出去'],['英语 evacuate','撤离、疏散；使空间腾空']]
W=[
E('vacation','/veɪˈkeɪʃən/','假期；休假、度假','把一段时间从日常工作里空出来，让自己暂时不被原来的职责占满。','经法语等路线来自拉丁 vacatio，与 vacare“空着、闲着”有关；英语 vacation 早于 vacate，不能说是后者才造出的名词。',V+[['拉丁 vacatio → 法语 vacacion','免于职责、空闲'],['英语 vacation','工作或学习的休止期；假期']],'vacation 在美式英语里常说假期或度假。on vacation 是正在休假，不一定已经坐飞机去远方，在家休息也可以。词根帮你抓住“从惯常事务里空出来”，不要误解为假期必须什么都不做。','take a vacation；go on vacation；summer vacation；vacation in a place。','英式英语常用 holiday；vacancy 则是房间或职位的空缺，不能互换。',('I’m taking a short vacation after the project ends.','项目结束后，我准备休一个短假。'),('We spent our vacation at home and explored the neighbourhood.','我们在家度过假期，逛了逛附近的街区。'),sources=['https://www.etymonline.com/word/vacation','https://en.wiktionary.org/wiki/vacation']),
E('vacant','/ˈveɪkənt/','空着的；无人占用的；茫然的','位置在那里，但该在里面的人、物或注意力没有占着它。','来自法语 vacant、拉丁 vacans，后者是 vacare 的分词形式。',V+[['拉丁 vacans → 法语 vacant','空着的、闲着的'],['英语 vacant','无人使用、尚未填补的']],'a vacant seat 是没人坐的座位；a vacant post 是尚未有人任职的职位。a vacant expression 是茫然的表情，好像注意力不在眼前，但不能仅凭这个形容就诊断一个人的心理或认知情况。','a vacant room；a vacant position；a vacant look。','empty 适用范围更广，vacant 常突出没有人占用或职位未填补；available 则强调可供使用，未必物理上空着。',('There is a vacant seat near the window.','窗边有一个空座位。'),('The company is trying to fill three vacant positions.','公司正在招聘，以填补三个空缺职位。'),sources=['https://en.wiktionary.org/wiki/vacant','https://www.etymonline.com/word/vacant']),
E('vacancy','/ˈveɪkənsi/','空缺职位；空房；空置状态','把“这里空着”变成一个可被填补的空位或一种状态。','来自晚期拉丁 vacantia，与 vacans、vacare 同族；现代可联系 vacant 与 -ancy 的名词关系。',V+[['晚期拉丁 vacantia','空着的状态'],['英语 vacancy','空缺；职位或房间的空位']],'旅馆标着 No vacancies，通常是没有空房，不是员工都没请假。a job vacancy 是一份待人申请的工作；vacancy rate 是空置率或空缺率，具体看谈的是房屋还是岗位。','a job vacancy；fill a vacancy；No vacancies；vacancy rate。','vacation 是假期，vacancy 是空缺。一个人去 vacation 休假，不一定产生永久 job vacancy。',('Do you have any vacancies for next weekend?','你们下周末还有空房吗？'),('The school advertised a vacancy for a music teacher.','学校发布了音乐教师岗位的招聘信息。'),sources=['https://en.wiktionary.org/wiki/vacancy','https://www.etymonline.com/word/vacancy']),
E('vacate','/veɪˈkeɪt/','搬离；腾出；撤销〔法律用语〕','从原来占着的位置离开，让那个地方空出来。','与拉丁 vacare“空着”相关；早期英语有撤销、使失效的法律用法，具体借入形式有不同分析。',V+[['拉丁 vacare 相关形式 → 早期英语 vacate','使失效、撤销'],['英语 vacate 的日常引申','离开房间、位置或职务，腾出空位']],'Please vacate the room by ten 是请十点前离开并腾出房间，比 leave 更正式。vacate a seat 是让出座位，vacate an office 可说离任。法律中的 vacate a judgment 是撤销判决，不是把判决搬到别处。','vacate a room；vacate the premises；vacate a position。','vacate 多说腾出你占用的地方，evacuate 常说因危险组织撤离；离开酒店不必用紧急意味的 evacuate。',('Guests must vacate their rooms by eleven.','客人须在十一点前腾出房间。'),('He vacated the chair so that the older visitor could sit down.','他让出椅子，让那位年长的访客坐下。'),sources=['https://www.etymonline.com/word/vacate','https://en.wiktionary.org/wiki/vacate']),
E('evacuate','/ɪˈvækjueɪt/','疏散；撤离；排空','把里面的人或东西转移出去，让原来的地方空下来。','拉丁 e-〔ex-，向外〕+ vacuus“空的”组成 evacuare；英语动词与其分词形式有关。',EV,'evacuate the building 是撤离或疏散楼里的人；evacuate residents 是把居民转移出去。两个宾语都可以成立：有时说腾空哪里，有时说转移谁。新闻中的用法通常与危险有关，但本义“排空”也保留在技术语境里。','evacuate a building；evacuate residents；evacuate to safety。','evacuate 是撤离，escape 是逃脱；有组织的疏散不一定是仓皇逃跑。vacate 可只是正常腾房。',('Staff evacuated the building when the alarm sounded.','警报响起后，工作人员撤离了大楼。'),('Rescuers evacuated the residents before the river flooded.','河水泛滥前，救援人员转移了居民。'),sources=['https://www.etymonline.com/word/evacuate','https://en.wiktionary.org/wiki/evacuate']),
E('evacuation','/ɪˌvækjuˈeɪʃən/','疏散、撤离；排空','把人员向外转移这件事，作为一次行动或一个流程来谈。','经法语及晚期拉丁 evacuatio 借入；与 evacuate 平行同源，现代能对应动词与 -ion 的关系。',V+[['拉丁 evacuare → evacuatio','排空 → 排空行为'],['法语 evacuation → 英语 evacuation','排空；后来用于人员撤离']],'an evacuation plan 是撤离安排，an evacuation drill 是练习怎么撤离。这个词强调过程，不等于灾害已经发生；演练也可以涉及 evacuation。新闻里的 mass evacuation 则指大量人员转移。','an evacuation plan；an evacuation drill；order an evacuation。','evacuation 是撤离过程；rescue 是救援，二者可能重叠，但不完全相同。',('The school holds an evacuation drill every term.','学校每学期都进行一次疏散演练。'),('Heavy rain delayed the evacuation of the village.','大雨延误了村庄人员的撤离。'),sources=['https://en.wiktionary.org/wiki/evacuation','https://www.etymonline.com/word/evacuate']),
E('vacuum','/ˈvækjuːm/','真空；空缺；吸尘器；用吸尘器清洁','核心是空出来的空间；生活用法又连接到利用气压差吸走灰尘。','拉丁 vacuus“空的”的中性形式 vacuum 可作名词“空的空间”；进入科学英语后保留这个拼写。',V+[['拉丁 vacuum → 科学英语 vacuum','空的空间；真空'],['vacuum cleaner 的缩略及相关动词','吸尘器；吸尘']],'实验中的 vacuum 指真空或很低气压的状态；power vacuum 是原来掌权者离开后留下的权力空缺。日常说 vacuum the carpet，就是用吸尘器清洁地毯，不是把整个房间变成真空。in a vacuum 则比喻脱离周围条件单独发生。','a vacuum cleaner；vacuum the floor；a power vacuum；in a vacuum。','vacuum 强调空间或相应技术状态，vacancy 常是房间、岗位的空缺。吸尘器利用气流，不能按名称想成内部绝对没有空气。',('Please vacuum the carpet before the guests arrive.','客人到来前，请用吸尘器清洁地毯。'),('These decisions cannot be made in a vacuum.','这些决定不能脱离周围情况来作。'),sources=['https://en.wiktionary.org/wiki/vacuum','https://www.merriam-webster.com/dictionary/vacuum']),
E('vacuous','/ˈvækjuəs/','空洞的；缺少思想内容的；茫然的','外面像说了很多话，里面却没多少有意义的内容。','拉丁 vacuus“空的” + 英语形容词后缀 -ous；由空间的空引申到思想内容的空。',V+[['拉丁 vacuus → 英语 vacuous','空的'],['意义转用于思想和表达','空洞、缺乏内容的']],'a vacuous comment 不是音量小，而是没有实质；vacuous slogans 是听起来响亮却没内容的口号。这个词通常带批评，不宜拿来中性描述一个暂时走神的人。','vacuous remarks；a vacuous statement；vacuous promises。','vague 是不清楚、不具体，vacuous 是空洞、缺少思想，两种问题可能同时出现，但不是同一个意思。',('The article replaces serious analysis with vacuous slogans.','文章用空洞的口号代替了严肃分析。'),('She was tired of hearing the same vacuous promises.','她已经听厌了那些一再重复的空洞承诺。'),sources=['https://www.etymonline.com/word/vacuous','https://en.wiktionary.org/wiki/vacuous'])]
ROOT=dict(id='C1597',meaning='空着、闲着；腾空与空缺',core='VAC = EMPTY / FREE',image='一个房间空着是 vacant；把它腾出来是 vacate；把人疏散出去是 evacuate；从工作中空出一段时间就是 vacation 的意义联系。',intro='拉丁 vacare“空着、闲着”与 vacuus“空的”是本组核心。空可以是空间无人占用，也可以是职责暂停，或比喻内容不足。各英语词分别经拉丁、法语等路线传入，不是把现代 vacation 拆开再造出的词族。',forms='vacant 说状态，vacancy 说空缺；vacate 是腾出，evacuate 加上向外的意义，evacuation 是相关行动名词。vacuum 保留拉丁中性名词形式的双 u；vacuous 是空洞的。',branches=[['空下时间和位置','vacation, vacant, vacancy, vacate'],['使里面空出来','evacuate, evacuation'],['空间空、内容空','vacuum, vacuous']],contrasts='vacation 是假期，vacancy 是空缺。正常退房可以 vacate，因危险撤离常用 evacuate。vacuum 与 vacuous 同有“空”的画面，但一个常谈空间，一个常批评内容。',practice='After the guests vacated the room, a vacant sign appeared at reception.\n\n客人腾出房间后，前台挂出了有空房的牌子。',words=[w['word'] for w in W],exclude={})
if __name__=='__main__':
 for name,data in [('roots_vac',[ROOT]),('words_vac',W)]:Path('.cache/batch200/drafts/root/'+name+'.json').write_text(json.dumps(data,ensure_ascii=False,indent=2))
 print(len(W),sum(len(w['examples']) for w in W))
